/*
**
* This function validates the message type in header
* @param {CamelExchange} exchange - The exchange.
*/
function validateHeader(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var msgType = getHeader(map, "PaymentType");
	msgType = msgType.toUpperCase();
	if(!msgType){
		var msgType = getHeader(map, "PLCN_MsgType");
	}
	logger.info("In validateHeader");
	
	logger.info("validateHeader: msgType = " + msgType);

	var msgTypeLib = msgType.toUpperCase();
	logger.info("validateHeader: msgTypeLib = " + msgTypeLib);
	
	if(isPatternPresent(msgTypeLib, "CBPR")) {
		
		var cbprDate = memTblGetTableValue(map, "USER_CONFIG_MAP", "CBPR_LIB2025_DATE");
		logger.info("validateHeader: cbprDate = " + cbprDate);
		
		var sysDate = getDate();
		logger.info("validateHeader: sysDate = " + sysDate);
		
		if(parseInt(sysDate) >= parseInt(cbprDate)){
			logger.info("validateHeader: CBPR 2025 XSD check configured");
			setHeader(map, "PLCN_CBPR2025_XSDCHECK", true);
		}
	}
	
	if(msgType == "CBPRPACS.009.001.08") {
		setHeader(map, "PLCN_headerFlag", true);

		var SttlmMtdPath = '/Document/FICdtTrf/GrpHdr/SttlmInf/SttlmMtd';
		var SttlmMtd = getValueFromPath(Document, SttlmMtdPath);
		logger.info("validateHdr: SttlmMtd = " + SttlmMtd);

		if(SttlmMtd == "COVE") {
			msgType = msgType + "ADV";
		}

		setHeader(map, "RevisedPaymentType", msgType);
	}else if(msgType == "SEPAPACS.004.001.09") {
		setHeader(map, "PLCN_headerFlag", true);

		var orgnlMsgNmIdPath = '/Document/PmtRtr/OrgnlGrpInf/OrgnlMsgNmId';
		var orgnlMsgNmId = getValueFromPath(Document, orgnlMsgNmIdPath);

		if(!orgnlMsgNmId){
			var orgnlMsgNmIdPath = '/Document/PmtRtr/TxInf/OrgnlGrpInf/OrgnlMsgNmId';
			var orgnlMsgNmId = getValueFromPath(Document, orgnlMsgNmIdPath);			
		}
		logger.info("validateHdr: orgnlMsgNmId = " + orgnlMsgNmId);

		/*if(orgnlMsgNmId == "camt.056.001.08") {
			msgType = msgType + "POS";
		}*/

		var rsnCdPath = '/Document/PmtRtr/TxInf/RtrRsnInf/Rsn/Cd';
		var rsnCd = getValueFromPath(Document, rsnCdPath);
		logger.info("validateHdr: rsnCd = " + rsnCd);

		if(rsnCd == 'FOCR'){
			msgType = msgType + "POS";
		}else{
			var mndtRltdInfPath = "Document/PmtRtr/TxInf/OrgnlTxRef/MndtRltdInf";
			var mndtRltdInf = getValueFromPath(Document, mndtRltdInfPath);
			logger.info("validateHdr: mndtRltdInf = " + mndtRltdInf);

			if(mndtRltdInf) {
				msgType = msgType + "SDD";
			}else if(orgnlMsgNmId == "pacs.003.001.08") {
				msgType = msgType + "SDD";
			}
		}
		logger.info("validateHdr: msgType = " + msgType);
		setHeader(map, "RevisedPaymentType", msgType);

	}else if(msgType == "SEPAPACS.002.001.10") {

		var orgnlMsgNmIdPath = '/Document/FIToFIPmtStsRpt/OrgnlGrpInfAndSts/OrgnlMsgNmId';
		var orgnlMsgNmId = getValueFromPath(Document, orgnlMsgNmIdPath);

		if(!orgnlMsgNmId){
			var orgnlMsgNmIdPath = '/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlGrpInfAndSts/OrgnlMsgNmId';
			var orgnlMsgNmId = getValueFromPath(Document, orgnlMsgNmIdPath);			
		}
		logger.info("validateHdr: orgnlMsgNmId = " + orgnlMsgNmId);

		if(orgnlMsgNmId == "pacs.003.001.08"){
			msgType = msgType + "SDD";
		}

		setHeader(map, "PLCN_headerFlag", true);
		setHeader(map, "RevisedPaymentType", msgType);
	}else if(msgType == "SEPACAMT.056.001.08") {

		var orgnlMsgNmIdPath = '/Document/FIToFIPmtCxlReq/Undrlyg/TxInf/OrgnlGrpInf/OrgnlMsgNmId';
		var orgnlMsgNmId = getValueFromPath(Document, orgnlMsgNmIdPath);

		logger.info("validateHdr: orgnlMsgNmId = " + orgnlMsgNmId);

		if(orgnlMsgNmId == "pacs.003.001.08"){
			msgType = msgType + "SDD";
		}

		setHeader(map, "PLCN_headerFlag", true);
		setHeader(map, "RevisedPaymentType", msgType);
	}else if(msgType == "SEPAINSTPACS.002.001.10") {
		var grpStsPath = 'Document/FIToFIPmtStsRpt/OrgnlGrpInfAndSts/GrpSts';
		var grpStsValue =getValueFromPath(Document, grpStsPath);
		logger.info("validateHdr: grpStsValue = " + grpStsValue);

		if(grpStsValue == "ACCP") {
			msgType = msgType + "POS";
		}else{
			msgType = msgType + "NEG";
		}

		logger.info("validateHdr: msgType = " + msgType);
		setHeader(map, "PLCN_headerFlag", true);
		setHeader(map, "RevisedPaymentType", msgType);
	}else if(msgType == "TARGET2PACS.002.001.10" || msgType == "TARGET2PACS.004.001.09" || msgType == "TARGET2PACS.008.001.08" || msgType == "TARGET2PACS.009.001.08" || msgType == "CBPRPACS.002.001.10" || msgType == "CBPRPACS.004.001.09" || msgType == "CBPRPACS.008.001.08" || msgType == "CBPRCAMT.057.001.06" || msgType == "CBPRPAIN.001.001.09" || msgType == "CBPRPAIN.002.001.10" || msgType == "SEPAPACS.008.001.08" || msgType == "SEPAPACS.004.001.09" || msgType == "SEPACAMT.029.001.09" || msgType == "SEPACAMT.056.001.08" || msgType == "SEPAPACS.002.001.10"|| msgType == "SEPAPACS.003.001.08"|| msgType == "SEPAPACS.007.001.09" || msgType == "LYNXPACS.008.001.08" || msgType == "LYNXPACS.009.001.08" || msgType == "SEPAINSTPACS.008.001.08" || msgType == "SEPAINSTPACS.004.001.09" || msgType == "SEPAINSTCAMT.056.001.08" || msgType == "SEPAINSTCAMT.029.001.09" || msgType == "SEPAINSTPACS.028.001.03" || msgType == "SEPAINSTPACS.002.001.10" || msgType == "CBPRCAMT.053.001.08" || msgType == "CbprPacs009cov" || msgType == "LynxPacs008" || msgType == "LynxPacs009" || msgType == "CbprPacs009adv" || msgType == "ChipsPacs008" || msgType == "ChipsPacs009" || msgType == "ChipsPacs004" || msgType == "CbprPacs002" || msgType == "CbprPacs004" || msgType == "CbprPacs008" || msgType == "CbprPacs009" || msgType == "FedPacs004" || msgType == "FedPacs008" || msgType == "FedPacs009") {
		setHeader(map, "PLCN_headerFlag", true);
		setHeader(map, "RevisedPaymentType", msgType);
		if(msgType=="CbprPacs008")
		{
			setHeader(map, "RevisedPaymentType", "CBPRPACS.008.001.08");
		}
		else if(msgType =="CbprPacs009")
		{
			setHeader(map, "RevisedPaymentType", "CBPRPACS.009.001.08");
		}
		else if(msgType =="CbprPacs004")
		{
			setHeader(map, "RevisedPaymentType", "CBPRPACS.004.001.09");
		}
		else if(msgType =="CbprPacs002")
		{
			setHeader(map, "RevisedPaymentType", "CBPRPACS.002.001.10");
		}
		else if(msgType =="CbprPacs009adv")
		{
			setHeader(map, "RevisedPaymentType", "CBPRPACS.009.001.08ADV");
		}
		else if(msgType =="CbprPacs009cov")
		{
			setHeader(map, "RevisedPaymentType", "CBPRPACS.009.001.08COV");
		}
		else if(msgType =="FedPacs004")
		{
			setHeader(map, "RevisedPaymentType", "FEDPACS.004.001.10");
		}
		else if(msgType =="FedPacs008")
		{
			setHeader(map, "RevisedPaymentType", "FEDPACS.008.001.08");
		}
		else if(msgType =="FedPacs009")
		{
			setHeader(map, "RevisedPaymentType", "FEDPACS.009.001.08");
		}
	}else if(msgType == "CBPRACKX") {
		setHeader(map, "PLCN_headerFlag", true);
		setHeader(map, "PLCN_ackx_check", true);
		setHeader(map, "RevisedPaymentType", msgType);
	}else if(msgType == "CBPRNAKX") {
		setHeader(map, "PLCN_headerFlag", true);
		setHeader(map, "PLCN_nakx_check", true);
		setHeader(map, "RevisedPaymentType", msgType);
	}else {
		setHeader(map, "PLCN_headerFlag", false);
		setHeader(map, "headerFlag", false);
		setHeader(map, "PLCN_validMessage", false);
		setHeader(map, "PLCN_exceptionFlag", true);
		setHeader(map, "PLCN_INVALID_MESSAGE_TYPE", true);
		setCommentsForTransaction ("117", "6868",map);
	}

	logger.info("validateHdr: PLCN_headerFlag = " + getHeader(map, "PLCN_headerFlag"));
	logger.info("validateHdr: typeof PLCN_headerFlag = " + typeof getHeader(map, "PLCN_headerFlag"));
}

function setResponseCode(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	
	var jsHelper = new JSHelperClass();
	logger.trace("setResponseCode: responseCdsDoc = " + responseCdsDoc);
	logger.trace("setResponseCode: typeof responseCdsDoc = " + typeof responseCdsDoc);

	var responseCdsDoc = getHeader(map, "PLCN_responseCdsDoc");

	logger.info("setResponseCode: responseCdsDoc = " + responseCdsDoc);
	logger.info("setResponseCode: typeof responseCdsDoc = " + typeof responseCdsDoc);

	var xsdValid = getHeader(map, "XSD_VALID");
	logger.info("setResponseCode: xsdValid = " + xsdValid);

	if(!xsdValid) {
		setHeader(map, "PLCN_validMessage", false);
		setHeader(map, "status", "error");
	}

	var creationCall = getHeader(map, "PLCN_creationCall");
	logger.info("setResponseCode: creationCall = " + creationCall);

	if(responseCdsDoc) {
		var responseCdsString = convertDocumentToString(responseCdsDoc);
		var encodedBody = Base64.getEncoder().encodeToString(jsHelper.getBytes(responseCdsString));
		logger.trace("setResponseCode: encodedBody = " + encodedBody);
		setHeader(map, "PLCN_responseNanBody", encodedBody);
		logger.info("setResponseCode: responseCdsString = " + responseCdsString);
		inMsg.setBody(responseCdsString);
	}
	
	var txnComments = getHeader(map, "PLCN_txnComments"); 
	if(!responseCdsDoc && txnComments && creationCall != "true"){
		responseCdsDoc = createResponseValidationSetResponseCode(exchange);
		logger.trace("setResponseCode: After createResponseValidation ");
		logger.trace("setResponseCode: responseCdsDoc = "+ responseCdsDoc);
		var xmlform = '<?xml version="1.0" encoding="UTF-8" standalone="no"?>';
		responseCdsDoc=xmlform+responseCdsDoc;
		logger.trace("setResponseCode: responseCdsDoc + xmlform = "+ responseCdsDoc);
		var encodedBody = Base64.getEncoder().encodeToString(jsHelper.getBytes(responseCdsDoc));
		logger.trace("setResponseCode: encodedBody = " + encodedBody);
		setHeader(map, "PLCN_responseNanBody", encodedBody);
		inMsg.setBody(responseCdsDoc);
	}
}

function encodeResponseCode(exchange) {
	var helper;
	var encodedResponseCode;
	var message;
	var inMsg;
	var header;
	var messagebody;
	logger.info("In encodeResponseCode");

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var responseCode = getHeader(map, "PLCN_responseCdsDoc");

	logger.trace("encodeResponseCode: responseCode = " + responseCode);
	logger.info("encodeResponseCode: typeof responseCode = " + typeof responseCode);

	helper = new JSHelperClass();
	encodedResponseCode = Base64.getEncoder().encodeToString(helper.getBytes(responseCode));
	logger.trace("encodeResponseCode: encodedResponseCode = " + encodedResponseCode);
	logger.info("encodeResponseCode: typeof encodedResponseCode = " + typeof encodedResponseCode);

	setHeader(map, "PLCN_responseCdsDoc", encodedResponseCode);
}

function createResponseValidation(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var i;
	var j = 0;
	var k;
	var fldNo = [];
	var fldViolation = [];
	var ofldViolation = [];
	var fldTag;
	var fldName;
	var plcnCodesValues;
	var ovCount = 0;
	var vCount = 0;
	var responseCdsString;
	var CdTpValue = [];
	var t2Status;

	logger.info("In createResponseValidation");

	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	logger.trace("createResponseValidation: typeof Document = " + typeof Document);

	var validMessage = getHeader(map, "PLCN_validMessage");
	var msgType = getHeader(map, "PLCN_msgType");
	var status = getHeader(map, "status");

	var plcnFlag = getHeader(map, "PLCN_call");
	logger.info("createResponseValidation: plcnFlag = " + plcnFlag);
	logger.info("createResponseValidation: typeof plcnFlag = " + typeof plcnFlag);

	var xsdValid = getHeader(map, "XSD_VALID");
	logger.info("createResponseValidation: xsdValid = " + xsdValid);
	logger.info("createResponseValidation: typeof xsdValid = " + typeof xsdValid);

	var t2Valid = getHeader(map, "PLCN_t2Valid");
	logger.info("createResponseValidation: t2Valid = " + t2Valid);
	logger.info("createResponseValidation: typeof t2Valid = " + typeof t2Valid);


	//if its an internal call response code is stored in ACEDB_responseCdsDoc (in T2 & CBPR server) otherwise PLCN_responseCdsDoc 
	if(plcnFlag.toString() == "true") {
		if(xsdValid.toString() == "false") {
			responseCdsString = getHeader(map, "ACEDB_responseCdsDoc");
			logger.info("createResponseValidation: ACEDB_responseCdsDoc = " + responseCdsString);
		}else {
			responseCdsString = null;
			logger.info("createResponseValidation: setting responseCdsString = null in plcnFlag.toString() == true + responseCdsString");
		}
	}else {
		if(xsdValid.toString() == "false" /*|| t2Valid.toString() == "false"*/) {
			responseCdsString = getHeader(map, "PLCN_responseCdsDoc");
			logger.info("createResponseValidation: PLCN_responseCdsDoc = " + responseCdsString);
		}else {
			responseCdsString = null;
		}
	}

	logger.trace("createResponseValidation: responseCdsString = " + responseCdsString);
	logger.info("createResponseValidation: typeof responseCdsString = " + typeof responseCdsString);

	logger.trace("createResponseValidation: validMessage = " + validMessage);
	logger.info("createResponseValidation: typeof validMessage = " + typeof validMessage);
	logger.info("createResponseValidation: status = " + status);
	logger.info("createResponseValidation: msgType = " + msgType);

	if(!msgType) {
		var documentString = inMsg.getBody(java.lang.String.class);

		if(isPatternPresent(documentString, "<FIToFIPmtStsRpt>")) {
			msgType = "pacs.002.001.10";
		}else if(isPatternPresent(documentString, "<PmtRtr>")) {
			msgType = "pacs.004.001.09";
		}else if(isPatternPresent(documentString, "<FIToFICstmrCdtTrf>")){
			msgType = "pacs.008.001.08";
		}else if (isPatternPresent(documentString, "<FICdtTrf>")) {
			msgType = "pacs.009.001.08";
		}else if (isPatternPresent(documentString, "<NtfctnToRcv>")) {
	        msgType = "camt.057.001.06";
	    }

	    logger.info("createResponseValidation: msgType = " + msgType);
	}

	var txnComments = getHeader(map, "PLCN_txnComments"); //"P00-1P32-1:A00:00-9505:A00:32-6012:A00:32-6013";
	var orgnlComments = getHeader(map, "PLCN_orgnlComments"); //"P00-1:A00:00-9505";
	var txnCommentsDB = txnComments;

	logger.info("createResponseValidation: txnComments = " + txnComments);
	logger.info("createResponseValidation: orgnlComments = " + orgnlComments);

	if(orgnlComments) {
		ovCount = (orgnlComments.match(/:A00:/g)).length;
	}
	var comments = txnComments + ":A00:";

	logger.info("createResponseValidation: ovCount = " + ovCount);
	logger.info("createResponseValidation: comments = " + comments);

	orgnlComments = orgnlComments + ":A00:";

	for(k = 0; k < ovCount; k++) {
		var otmp = dataBetweenTokens(":A00:", ":A00:", orgnlComments);
		logger.info("createResponseValidation: otmp = " + otmp);
		ofldViolation[k] = otmp.substring(3, 7);
		comments = removePattern(comments, ":A00:" + otmp);
		orgnlComments = removePattern(orgnlComments, ":A00:" + tmp);
	}

	logger.info("createResponseValidation: comments = " + comments);
	logger.info("createResponseValidation: orgnlComments = " + orgnlComments);
	logger.info("createResponseValidation: txnComments = " + txnComments);

	plcnCodesValues = comments.substring(0, comments.length - 5);
	logger.info("createResponseValidation: plcnCodesValues = " + plcnCodesValues);

	logger.info("createResponseValidation: txnComments = " + txnComments);
	logger.info("createResponseValidation: txnComments length = " + txnComments.length);
	logger.info("createResponseValidation: typeof txnComments = " + typeof txnComments);

	if(txnComments.length > 0) {
		vCount = (txnComments.match(/:A00:/g)).length;//(txnComments.match(/:A00:/g) || []).length;
		logger.info("createResponseValidation: vCount = " + vCount);
	}

	for(i = 0; i < vCount; i++) {
		logger.info("createResponseValidation: txnComments = " + txnComments);
		var tmp = dataBetweenTokens(":A00:", ":A00:", txnComments); //296-5770
		logger.info("createResponseValidation: tmp = " + tmp);
		var tmp2 = ":A00:" + tmp + ":A00:" //:A00:296-5770:A00:
		logger.info("createResponseValidation: tmp2 = " + tmp2);
		fldNo[i] = dataBetweenTokens(":A00:", "-", tmp2); //tmp.substring(0, 2);
		fldViolation[i] = dataBetweenTokens("-", ":A00:", tmp2); //tmp.substring(3, 7);
		txnComments = removePattern(txnComments, ":A00:" + tmp);
	}

	logger.info("createResponseValidation: fldViolation = " + fldViolation);
	logger.info("createResponseValidation: fldNo = " + fldNo);

	logger.trace("createResponseValidation: responseCdsString = " + responseCdsString);
	logger.info("createResponseValidation: typeof responseCdsString = " + typeof responseCdsString);

	logger.info("createResponseValidation: txnCommentsDB = " + txnCommentsDB);
	logger.info("createResponseValidation: typeof txnCommentsDB = " + typeof txnCommentsDB);

	if(responseCdsString != null) {
		//append
		logger.info("createResponseValidation: response code already generated");
		setHeader(map, "xsdStatus", "error");
		setHeader(map, "status", "error");

		if(plcnFlag == "true") {
			var responseDoc = createDocument(responseCdsString);
		}else {
			var responseDoc = responseCdsString;
		}

		logger.info("createResponseValidation: typeof responseDoc = " + typeof responseDoc);

		var responseCdsPlcnFmt = responseDoc.getElementsByTagName("ResponseCdsPlcnFmt");
		var nextNode = responseCdsPlcnFmt.item(0);

		//responseDoc = createResponseValidationXml(responseDoc, nextNode, fldNo, fldViolation);

		while(j < vCount) {

			if(msgType) {
				fldTag = memTblGetTableValue(map, msgType + "FldTag", fldNo[j]);
				fldTag = fldTag.trim();
				fldName = memTblGetTableValue(map, msgType + "FldName", fldTag);
				fldName = fldName.trim();				
			}

			logger.info("createResponseValidation: fldTag = " + fldTag);
			logger.info("createResponseValidation: fldName = " + fldName);

			var responseCds = responseDoc.getElementsByTagName("ResponseCds"); //root element
			//logger.info("createResponseValidation: responseCds = " + convertDocumentToString(responseCds));
			logger.trace("createResponseValidation: typeof responseCds = " + typeof responseCds);

			var AddtlResponseCds = createElementwithTextNode2(responseDoc, "AddtlResponseCds", "");
			//logger.info("createResponseValidation: AddtlResponseCds = " + convertDocumentToString(AddtlResponseCds));
			//appendElementtoNode(responseCds, AddtlResponseCds);
			var newNode = responseCds.item(0);
			newNode.insertBefore(AddtlResponseCds, nextNode);

			var PlcnFldNum = createElementwithTextNode2(responseDoc, "PlcnFldNum", fldNo[j]);
			appendElementtoNode(AddtlResponseCds, PlcnFldNum);

			if(fldTag) {
				var FldTag = createElementwithTextNode2(responseDoc, "FldTag", fldTag);
				appendElementtoNode(AddtlResponseCds, FldTag);
			}

			if(fldName) {
				var FldName = createElementwithTextNode2(responseDoc, "FldName", fldName);
				appendElementtoNode(AddtlResponseCds, FldName);
			}

			var violationSeries = fldViolation[j].substring(0, 1);
			logger.info("createResponseValidation: violationSeries = " + violationSeries);

			if(violationSeries == "8" || violationSeries == "1") {
				CdTpValue = "Error";
			}else if(violationSeries == "7") {
				CdTpValue = "Warning";
			}else if(violationSeries == "9") {
				CdTpValue = "Repair";
			}else if(violationSeries == "6") {
				CdTpValue = "Info";
			}else {
				CdTpValue = "Info";
			}

			logger.info("createResponseValidation: CdTpValue = " + CdTpValue);

			var CdTp = createElementwithTextNode2(responseDoc, "CdTp", CdTpValue);
			appendElementtoNode(AddtlResponseCds, CdTp);

			var Code = createElementwithTextNode2(responseDoc, "Cd", fldViolation[j]);
			appendElementtoNode(AddtlResponseCds, Code);

			var DescriptionValue = memTblGetTableValue(map, "LANGDESC", "PAYALY|" + fldViolation[j]);
			logger.info("createResponseValidation: DescriptionValue from PAYALY = " + DescriptionValue);

			if(!DescriptionValue) {
				DescriptionValue = memTblGetTableValue(map, "LANGDESC", "ACEERR|" + fldViolation[j]);
				logger.info("createResponseValidation: DescriptionValue from ACEERR = " + DescriptionValue);
			}

			if(!DescriptionValue) {
				DescriptionValue = "Unable to fetch description for given error/warning code. Please contact administrator.";
			}				

			var Description = createElementwithTextNode2(responseDoc, "Description", DescriptionValue);
			appendElementtoNode(AddtlResponseCds, Description);

			j++;
		}

		var responseCdsPath = "/ResponseCds/ResponseCdsPlcnFmt/PlcnCodes"
		var retVal = setValueInTxtNode(responseDoc, responseCdsPath, plcnCodesValues);
		logger.info("createResponseValidation: retVal = " + retVal);

		/*var fldViolationArray = getHeader(map, "fldViolationArray");

		for(i == 0; i < fldViolationArray.length; i++) {
			if(fldViolationArray[i].substring(0, 1) == "7"  || fldViolationArray[i].substring(0, 1) == "8") {
				setHeader(map, "status", "error");

				t2Status = "error";
			}
		}*/

		/*if(t2Status = "error") {
			var t2FldNo[] = "00";
			var t2FldViolation[] = "8001";

			nextNode = responseCdsPlcnFmt.item(0);	
			responseDoc = createResponseValidationXml(responseDoc, nextNode, t2FldNo, t2FldViolation);
		}*/

		setHeader(map, "PLCN_validMessage", "false");
	}else if(txnCommentsDB) {
		//create
		logger.info("createResponseValidation: creating response code");
		var responseDoc = getDocument();
		logger.trace("createResponseValidation: responseDoc = " + responseDoc);

		var responseCds = createElement(responseDoc, "ResponseCds");
		appendElementtoNode(responseDoc, responseCds);

		logger.info("createResponseValidation: j = " + j);
		logger.info("createResponseValidation: vCount = " + vCount);
		
		while(j < vCount) {
			if(msgType) {
				fldTag = memTblGetTableValue(map, msgType + "FldTag", fldNo[j]);
				fldTag = fldTag.trim();
				fldName = memTblGetTableValue(map, msgType + "FldName", fldTag);
				fldName = fldName.trim();				
			}

			logger.info("createResponseValidation: fldTag = " + fldTag);
			logger.info("createResponseValidation: fldName = " + fldName);

			var AddtlResponseCds = createElementwithTextNode(responseDoc, responseCds, "AddtlResponseCds", "");
			appendElementtoNode(responseCds, AddtlResponseCds);

			var PlcnFldNum = createElementwithTextNode(responseDoc, responseCds, "PlcnFldNum", fldNo[j]);
			appendElementtoNode(AddtlResponseCds, PlcnFldNum);

			if(fldTag) {
				var FldTag = createElementwithTextNode2(responseDoc, "FldTag", fldTag);
				appendElementtoNode(AddtlResponseCds, FldTag);
			}

			if(fldName) {
				var FldName = createElementwithTextNode2(responseDoc, "FldName", fldName);
				appendElementtoNode(AddtlResponseCds, FldName);
			}

			var violationSeries = fldViolation[j].substring(0, 1);
			logger.info("createResponseValidation: violationSeries = " + violationSeries);

			if(violationSeries == "8" || violationSeries == "1") {
				CdTpValue[j] = "Error";
			}else if(violationSeries == "7") {
				CdTpValue[j] = "Warning";
			}else if(violationSeries == "9") {
				CdTpValue[j] = "Repair";
			}else if(violationSeries == "6") {
				CdTpValue[j] = "Info";
			}else {
				CdTpValue[j] = "Info";
			}

			logger.info("createResponseValidation: CdTpValue = " + CdTpValue);

			var CdTp = createElementwithTextNode2(responseDoc, "CdTp", CdTpValue[j]);
			appendElementtoNode(AddtlResponseCds, CdTp);
			
			var Code = createElementwithTextNode(responseDoc, responseCds, "Cd", fldViolation[j]);
			appendElementtoNode(AddtlResponseCds, Code);

			var langDescKey = "PAYALY|" + fldViolation[j];
			var DescriptionValue = memTblGetTableValue(map, "LANGDESC", langDescKey);
			logger.info("createResponseValidation: langDescKey = " + langDescKey);
			logger.info("createResponseValidation: DescriptionValue = " + DescriptionValue);

			if(!DescriptionValue) {
				langDescKey = "ACEERR|" + fldViolation[j];
				DescriptionValue = memTblGetTableValue(map, "LANGDESC", langDescKey);
				logger.info("createResponseValidation: langDescKey = " + langDescKey);
				logger.info("createResponseValidation: DescriptionValue = " + DescriptionValue);
			}

			if(!DescriptionValue) {
				DescriptionValue = "Unable to fetch description for given error/warning code. Please contact administrator.";
				logger.info("createResponseValidation: DescriptionValue = " + DescriptionValue);
			}				

			var Description = createElementwithTextNode2(responseDoc, "Description", DescriptionValue);
			appendElementtoNode(AddtlResponseCds, Description);
			
			j++;
			logger.info("createResponseValidation: j count = " + j);
		}						

		var ResponseCdsPlcnFmt = createElementwithTextNode(responseDoc, responseCds, "ResponseCdsPlcnFmt", "");
		appendElementtoNode(responseCds, ResponseCdsPlcnFmt);

		var PlcnCodes = createElementwithTextNode(responseDoc, responseCds, "PlcnCodes", getHeader(map, "PLCN_txnComments"));
		appendElementtoNode(ResponseCdsPlcnFmt, PlcnCodes);

		logger.info("createResponseValidation: CdTpValue length = " + CdTpValue.length);

		for(j = 0; j < CdTpValue.length; j++) {
			logger.info("createResponseValidation: CdTpValue = " + CdTpValue[j]);

			if(CdTpValue[j] == "Error") {
				setHeader(map, "status", "error");
			}else{
				setHeader(map, "status", "valid");
			}
		}
	}

	logger.trace("createResponseValidation: responseDoc = " + responseDoc);
	logger.info("createResponseValidation: status = " + getHeader(map, "status"));

	if(responseDoc){
		logger.trace("createResponseValidation: responseDoc = " + responseDoc);
		var responseCdsString = getPrettyPrint(responseDoc);
		logger.trace("createResponseValidation: responseCdsString = " + responseCdsString);
		var internalFlag = getHeader(map, "PLCN_call");
		logger.info("createResponseValidation: internalFlag = " + internalFlag);

		if(!internalFlag){
			inMsg.setBody(responseCdsString);
		}else {
			setHeader(map, "ACEDB_responseCdsDoc", responseCdsString);
		}
	}
}

/*
**
* This function calls target2ValidationPacs02 and wrpr_B2B_Pacs002_RTGS function. Header variable PLCN_validMessage is set to true.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function msgValidationTarget2Pacs002(exchange) {
	var result;
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	logger.info("In msgValidationTarget2Pacs002");

	setHeader(map, "PLCN_txxnForceStopCounter", 0);
	setHeader(map, "PLCN_errorCountAdd", "Y");//for testing
	setHeader(map, "PLCN_validMessage", true);

	//wrprPacs02Mx(exchange);

	result = true; //getHeader(map, "PLCN_validMessage");
	logger.info("msgValidationTarget2Pacs002: PLCN_validMessage = " + result);
	logger.info("msgValidationTarget2Pacs002: typeof PLCN_validMessage = " + typeof result);

	var flag = memTblGetTableValue(map, "FLAG-TABLE", "PROCESS_T2ONLY");
	logger.info("msgValidationTarget2Pacs002: flag = " + flag);

	flag = flag.trim();

	if(result == true) {
		setHeader(map, "status", "valid");
	}else {
		setHeader(map, "status", "error");

		if(flag == "Y"){
			//T2 business rule failed
			setCommentsForTransaction("00", "8183", map);
		}
	}
}

