/*
**
* This function calls externalCodelistValidationTarget2Pacs008 and target2ValidationRulesPacs008 function. Header variable PLCN_validMessage is set to false if violation is raised otherwise it is set to true.
* @param {CamelExchange} exchange - The exchange.
*/
function wrapperC2bPacs008Mx(exchange) {
	var retVal;
	var commentsB2b;
	var pacs08ValdFlagMx;
	var txnComments;
	var inMsg;
	var map;
	var Document;
	var streamDetails;

	logger.info('In wrapperC2bPacs008Mx');
	logger.info("wrapperC2bPacs008Mx: exchange = " + exchange);
	logger.info("wrapperC2bPacs008Mx: typeof exchange = " + typeof exchange);

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	
	pacs08ValdFlagMx = memTblGetTableValue(map, "FLAG-TABLE", "PACS08_VALD_FLAG_MX");
	pacs08ValdFlagMx = pacs08ValdFlagMx.trim();
	logger.info("pacs08ValdFlagMx = " + pacs08ValdFlagMx);

	//memTblSetTableValue(map, "STREAM_DETAILS", "msgModeIn", "UPLOAD");

	if(pacs08ValdFlagMx == 'ERROR') {

		logger.info("wrapperC2bPacs008Mx: Calling target2ValidationRulesPacs008");
		retVal = target2ValidationRulesPacs008(pacs08ValdFlagMx, exchange);
		logger.info("wrapperC2bPacs008Mx: retVal from target2ValidationRulesPacs008 = " + retVal);
		txnComments = getHeader(map, 'txnComments');
		logger.info("wrapperC2bPacs008Mx: txnComments = " + txnComments);

		if(retVal == 0) {
			logger.info("wrapperC2bPacs008Mx: Calling externalCodelistValidationTarget2Pacs008");
			retVal = externalCodelistValidationTarget2Pacs008(Document, map);		
			txnComments = getHeader(map, 'txnComments');
			logger.info("txnComments from externalCodelistValidationTarget2Pacs008 = " + txnComments);			
		}

		if(retVal == 0) {
			logger.info("wrapperC2bPacs008Mx: Calling ibanValidationTarget2Pacs008");
			retVal = ibanValidationTarget2Pacs008(exchange);
			txnComments = getHeader(map, 'txnComments');
			logger.info("wrapperC2bPacs008Mx: txnComments from ibanValidationTarget2Pacs008 = " + txnComments);
		}
	}

	if(pacs08ValdFlagMx == 'WARNING') {

		logger.info("wrapperC2bPacs008Mx: Calling target2ValidationRulesPacs008");
		retVal = target2ValidationRulesPacs008(pacs08ValdFlagMx, exchange);
		logger.info("wrapperC2bPacs008Mx: retVal from target2ValidationRulesPacs008 = " + retVal);
		txnComments = getHeader(map, 'txnComments');
		logger.info("wrapperC2bPacs008Mx: txnComments = " + txnComments);

		logger.info("wrapperC2bPacs008Mx: Calling externalCodelistValidationTarget2Pacs008");
		retVal = externalCodelistValidationTarget2Pacs008(Document, map);		
		txnComments = getHeader(map, 'txnComments');
		logger.info("txnComments from externalCodelistValidationTarget2Pacs008 = " + txnComments);			
		

		logger.info("wrapperC2bPacs008Mx: Calling ibanValidationTarget2Pacs008");
		ibanValidationTarget2Pacs008(exchange);
		txnComments = getHeader(map, 'txnComments');
		logger.info("wrapperC2bPacs008Mx: txnComments from ibanValidationTarget2Pacs008 = " + txnComments);
	}
}

/*
**
* This function calls externalCodelistValidationTarget2Pacs009 and target2ValidationRulesPacs009 function. Header variable PLCN_validMessage is set to false if violation is raised otherwise it is set to true.
* @param {CamelExchange} exchange - The exchange.
*/
function wrapperC2bPacs009Mx(exchange) {
	var retVal = 0;
	var pacs09ValdFlag;

	logger.info('wrapperC2bPacs009Mx:In wrapperC2bPacs009Mx');
	
	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	pacs09ValdFlag = memTblGetTableValue(map, "FLAG-TABLE", "PACS09_VALD_FLAG_MX");

	if(pacs09ValdFlag = "ERROR") {
		retVal = target2ValidationRulesPacs09(pacs09ValdFlag,exchange);

		if(retVal == 0) {
			logger.info("wrapperC2bPacs009Mx: Calling externalCodelistValidation");
			retVal = externalCodelistValidationTarget2Pacs009(Document, map);		
			txnComments = getHeader(map, 'txnComments');
			logger.info("txnComments from externalCodelistValidation = " + txnComments);			
		}

		if(retVal == 0) {
			logger.info("wrapperC2bPacs009Mx: Calling ibanValidationTarget2Pacs009");
			retVal = ibanValidationTarget2Pacs009(exchange);
			txnComments = getHeader(map, 'txnComments');
			logger.info("wrapperC2bPacs009Mx: txnComments from ibanValidationTarget2Pacs009 = " + txnComments);
		}
	}

	if(pacs09ValdFlag = "WARNING") {
		retVal = target2ValidationRulesPacs09(pacs09ValdFlag, exchange);
		retVal = externalCodelistValidationTarget2Pacs009(Document, map);
		retVal = ibanValidationTarget2Pacs009(exchange);	
	}
}

