/*
**
* This function calls externalCodelistValidationCbprPacs009 and target2ValidationRulesPacs009 function. Header variable PLCN_validMessage is set to false if violation is raised otherwise it is set to true.
* @param {CamelExchange} exchange - The exchange.
*/
function wrapperCbprPacs009Mx(exchange) {
	var retVal = 0;
	var pacs09ValdFlag;
	var manualMode;
	var tenantName;

	logger.info('wrapperCbprPacs009Mx:In wrapperCbprPacs009Mx');
	
	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	pacs09ValdFlag = memTblGetTableValue(map, "FLAG-TABLE", "PACS09_VALD_FLAG_MX");
	
	manualMode = getHeader(map, "PLCN_manualMode");
	logger.info("wrapperCbprPacs009Mx: manualMode " +manualMode);

	var institutionId = getHeader(map, "PLCN_institutionId");
	tenantName = getHeader(map, "PLCN_tenantName");
	logger.info("wrapperCbprPacs009Mx: tenantName = " + tenantName);
	if(!tenantName){
		var tenantNamePath = institutionId + ".INSTITUTION_DETAILS.TENANT_NAME";
		logger.info("wrapperCbprPacs009Mx: tenantName = " + tenantNamePath);
		tenantName = memTblGetTableValue(map, "INST_PARAM",tenantNamePath);
		logger.info("wrapperCbprPacs009Mx: tenantName = " + tenantName);
	}
	
	if(pacs09ValdFlag = "ERROR") {
		retVal = cbprValidationRulesPacs009(pacs09ValdFlag, exchange);

		if(retVal == 0) {
			logger.info("wrapperCbprPacs009Mx: Calling externalCodelistValidation");
			retVal = externalCodelistValidationCbprPacs009(Document, map);		
			txnComments = getHeader(map, "PLCN_txnComments");
			logger.info("txnComments from externalCodelistValidation = " + txnComments);			
		}

		if(retVal == 0) {
			logger.info("wrapperCbprPacs009Mx: Calling ibanValidationCbprPacs008");
			retVal = ibanValidationCbprPacs009(exchange);
			txnComments = getHeader(map, "PLCN_txnComments");
			logger.info("wrapperCbprPacs009Mx: txnComments from ibanValidationCbprPacs008 = " + txnComments);
		}
		
		logger.info("wrapperCbprPacs009Mx: Added by Akshay ");
		logger.info("wrapperCbprPacs009Mx: retVal = " + retVal);
		logger.info("wrapperCbprPacs009Mx: manualMode = " + manualMode);
		logger.info("wrapperCbprPacs009Mx: tenantName = " + tenantName);
		
		if(retVal == 0 && manualMode == "REPAIR" && (tenantName == "SNTDBK")) {
		logger.info("wrapperCbprPacs009Mx: Calling sepaCBPRCustomValidationsPacs009");
		sepaCBPRCustomValidationsPacs009(pacs09ValdFlag,exchange);
		txnComments = getHeader(map, "PLCN_txnComments");
		logger.info("wrapperCbprPacs009Mx: txnComments from sepaCBPRCustomValidationsPacs009 = " + txnComments);
		}
		
	}



	if(pacs09ValdFlag = "WARNING") {
		retVal = cbprValidationRulesPacs009(pacs09ValdFlag, exchange);
		retVal = externalCodelistValidationCbprPacs009(Document, map);
		retVal = ibanValidationCbprPacs009(exchange);	
	}
}

