/*
**
* This function calls the validation function for particular fields
* @param {String} pacs02ValidFlag - Pacs002 valid mx flag value.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function target2ValidationPacs02(pacs02ValidFlag, Document, map){
	logger.info("In target2ValidationPacs02");
	var retVal;
	retVal = 0;
	
	if(pacs02ValidFlag == "ERROR"){
		retVal = mxPacs002TxSts(Document, map);
		if(retVal != 0){
			return retVal;
		}
		retVal = mxPacs002EffectiveInterbankSettlementDate(Document, map);
		if(retVal != 0){
			return retVal;
		}
	}
	
	if(pacs02ValidFlag == "WARNING"){
		retVal = mxPacs002TxSts(Document, map);
		retVal = mxPacs002EffectiveInterbankSettlementDate(Document, map);
	}	  
	return retVal;
}

/*
**
* This function checks TxSts value contains "ACSC" or "RJCT". If not then this function will raise appropriate violation.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function mxPacs002TxSts(Document, map){
	logger.info("In mxPacs002TxSts");
	var txStsPath;
	var txStsVal;
	var count;
	var retVal;
	retVal = 0;

	txStsPath = "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts";
	txStsVal = getValueFromPath(Document, txStsPath);
	txStsVal = txStsVal.trim();
	setHeader(map, "PLCN_custom12", txStsVal);
	logger.info("PLCN_custom12: " + getHeader(map, "PLCN_custom12"));
	logger.info("txStsVal: " + txStsVal);
	
	if(!(txStsVal == "ACSC" || txStsVal == "RJCT")) {
		retVal = setCommentsForTransaction("133", "1560",map);
		setHeader(map, "PLCN_validMessage", false);		
	}
	return retVal; //0	
}

/*
**
* wrapper_Enrich_Pacs002_Mx function 
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
*/
function wrapperEnrichPacs002Mx(Document, map){
	var msg;
	var orgnlGrpInf;
	var orgnlMsgId;
	var orgnlMsgNMID;
	var txSts;
	var txStsVal;
	var efctdt;
	var correlationId;
	var efctdtVal;
	var txnAccptnCDTTM;
	var txnInfo;
	var msgID;

	logger.info("In wrapper_Enrich_Pacs002_Mx");

	orgnlGrpInf = "/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlGrpInf";
	orgnlGrpInf = getValueFromPath(Document,orgnlGrpInf);
	logger.info("orgnlGrpInf: " + orgnlGrpInf);

	msgID = map.get("TRANSREFNO");

	if(!orgnlGrpInf){
		var newNode = createElementWithText(Document, "OrgnlMsgId",msgID);
		var newNode1 = createElementWithText(Document, "OrgnlMsgNmId", "pacs.008.001.08");
		var orgnlGrpInf_Path = "/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlGrpInf";
		var parentOrgnlGrpInf = getNode(Document, orgnlGrpInf_Path);
		if(parentOrgnlGrpInf == null)
		{
			path1 = '/Document/FIToFIPmtStsRpt/TxInfAndSts';
			logger.info("path1: "+ path1);
			var grandParent = getNode(Document,path1);
			logger.info("grandParent: "+ grandParent);
			parentOrgnlGrpInf = Document.createElement("OrgnlGrpInf");
			grandParent.appendChild(parentOrgnlGrpInf);
			var prevNode = '/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlEndToEndId';
			PrevNode = getNode(Document, prevNode);
			if(PrevNode == null){
				grandParent.appendChild(parentOrgnlGrpInf);
			}
			else{
				grandParent.insertBefore(parentOrgnlGrpInf, PrevNode);
			}
		}
		parentOrgnlGrpInf.appendChild(newNode1);
		parentOrgnlGrpInf.insertBefore(newNode, newNode1);

		//orgnlMsgId = "/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlGrpInf/OrgnlmsgId";
		//orgnlMsgNMID = "/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlGrpInf/OrgnlmsgNmId";
		/*txnInfo = "/Document/FIToFIPmtStsRpt/TxInfAndSts";
		
		if(txnInfo){
			correlationId = memTblGetTableValue(map, "STREAM_DETAILS", "ACE_MESSAGE_NO");
			orgnlMsgId = setValueInPath(Document,orgnlMsgId, correlationId);
		}
		orgnlMsgNMID = setValueInPath(Document,orgnlMsgNMID, "pacs.008.001.08");*/
	}
	
	txSts= "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts";
	txSts = getValueFromPath(Document,txSts);
	
	if(!txSts){
		txStsVal = "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts";
		txStsVal = setValueInPath(Document,txStsVal, "ACSC");
	}

	txSts = "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts";
	txSts = getValueFromPath(Document,txSts);

	efctdt = "/Document/FIToFIPmtStsRpt/TxInfAndSts/FctvIntrBkSttlmDt";
	efctdt = getValueFromPath(Document,efctdt);
	
	if(txSts){
		if(txSts == "ACSC"){
			if(!efctdt){
				efctdtVal = "/Document/FIToFIPmtStsRpt/TxInfAndSts/FctvIntrBkSttlmDt/DtTm";
				txnAccptnCDTTM = getDate();
				txnAccptnCDTTM = convertccyymmddIsoDate(txnAccptnCDTTM);
				txnAccptnCDTTM = txnAccptnCDTTM + "T" + LocalTime();
				efctdtVal = setValueInPath(Document,efctdtVal, txnAccptnCDTTM);
			}
		}
	}
}

/*
**
* mxPacs002EffectiveInterbankSettlementDate function checks if the TxSts value is "ACSC" then "FctvIntrBkSttlmDt" tag must be present, if the tag is absent - will raise appropriate violation.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function mxPacs002EffectiveInterbankSettlementDate(Document, map) {
	var txStsPath;
	var txStsVal;
	var fctvIntrBkSttlmDtPath;
	var fctvIntrBkSttlmDtValue;
	var retVal;
	retVal = 0;
	txStsPath = "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts";
	txStsVal = getValueFromPath(Document, txStsPath);
	
	if(txStsVal == "ACSC"){
		fctvIntrBkSttlmDtPath = "/Document/FIToFIPmtStsRpt/TxInfAndSts/FctvIntrBkSttlmDt";
		fctvIntrBkSttlmDtValue = getValueFromPath(Document, fctvIntrBkSttlmDtPath);
		if(!fctvIntrBkSttlmDtValue){
			retVal = setCommentsForTransaction("184", "1560",map);
			setHeader(map, "PLCN_validMessage", false);
		}
	}
	return retVal;
}

function target2ValidationRulesPacs004(pacs04ValdFlagMx, exchange){
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	logger.info("In target2ValidationRulesPacs004");
	logger.info("target2ValidationRulesPacs004: pacs04ValdFlagMx = " + pacs04ValdFlagMx);

	if(pacs04ValdFlagMx == "ERROR") {
		logger.info("target2ValidationRulesPacs004: pacs04ValdFlagMx = " + pacs04ValdFlagMx);

		retVal = target2AgentNamePstlAdrRulePacs4(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = target2StructuredvsUnstructuredRulePacs4(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = target2TownNameAndCountryRulePacs4(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValChrgsInfAgtBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValDbtrBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValInitgPtyAgtBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValDbtrAgtBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValPrvsInstgAgt1Bic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValPrvsInstgAgt2Bic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValPrvsInstgAgt3Bic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValIntrmyAgt1Bic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValIntrmyAgt2Bic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValIntrmyAgt3Bic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValCdtrAgtBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValinstgAgtBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		retVal = mxPacs004ValinstdAgtBic(exchange);

		if(retVal != 0) {
			return retVal;
		}

		/*retVal = checkAddressDetailsT2Pacs004(exchange);
		if(retVal != 0) {
			return retVal;
		}*/

		retVal = validateReasonCodeT2Pacs004(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = validateChrgsInfXchgRateT2Pacs004(exchange);
		if(retVal != 0) {
			return retVal;
		}
		retVal = crossElementComplexRulePacs004(pacs04ValdFlagMx,Document, map);
		if(retVal != 0) {
			return retVal;
		} 
	}

	if(pacs04ValdFlagMx == "WARNING") {
		logger.info("target2ValidationRulesPacs004: pacs04ValdFlagMx = " + pacs04ValdFlagMx);

		target2AgentNamePstlAdrRulePacs4(exchange);
		target2StructuredvsUnstructuredRulePacs4(exchange);
		target2TownNameAndCountryRulePacs4(exchange);
		mxPacs004ValChrgsInfAgtBic(exchange);
		mxPacs004ValDbtrBic(exchange);
		mxPacs004ValInitgPtyAgtBic(exchange);
		mxPacs004ValDbtrAgtBic(exchange);
		mxPacs004ValPrvsInstgAgt1Bic(exchange);
		mxPacs004ValPrvsInstgAgt2Bic(exchange);
		mxPacs004ValPrvsInstgAgt3Bic(exchange);
		mxPacs004ValIntrmyAgt1Bic(exchange);
		mxPacs004ValIntrmyAgt2Bic(exchange);
		mxPacs004ValIntrmyAgt3Bic(exchange);
		mxPacs004ValCdtrAgtBic(exchange);
		mxPacs004ValinstgAgtBic(exchange);
		mxPacs004ValinstdAgtBic(exchange);
		validateEnrichBicT2Pacs004(exchange);
		//checkAddressDetailsT2Pacs004(exchange);
		validateReasonCodeT2Pacs004(exchange);
		validateChrgsInfXchgRateT2Pacs004(exchange);
		crossElementComplexRulePacs004(pacs04ValdFlagMx,Document, map);
	}
}

function crossElementComplexRulePacs004(pacs04ValdFlagMx, Document, map) {
	var retVal;

	logger.info("In crossElementComplexRulePacs004");

	retVal = 0;

	if(pacs04ValdFlagMx == "ERROR") {

		 retVal = settlementMethodAgentRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}  
		retVal = settlementMethodCoverRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = settlementMethodCoverAgentRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		retVal = settlementMethodClearingRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		/*
		retVal = controlSumAndGroupReturnRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		} */

		retVal = returnReasonRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = amendmentIndicatorTrueRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = amendmentIndicatorFalseRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = returnedInstructedAmountAndExchangeRate1RulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = returnedInstructedAmountAndExchangeRate2RulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}	
		
		retVal = chargesInformationAndReturnedInstructedAmountRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		/* retVal = groupReturnAndNumberOfTransactionsRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		}	
		retVal = groupReturnAndReturnReasonRulePacs004(Document, map);
		if(retVal != 0) {
			return retVal;
		} */
	}

	if(pacs04ValdFlagMx == "WARNING") {

		retVal = settlementMethodAgentRulePacs004(Document, map);
		retVal = settlementMethodCoverRulePacs004(Document, map);
		retVal = settlementMethodCoverAgentRulePacs004(Document, map);
		retVal = settlementMethodClearingRulePacs004(Document, map);
		/*retVal = controlSumAndGroupReturnRulePacs004(Document, map); */
		retVal = returnReasonRulePacs004(Document, map);
		retVal = amendmentIndicatorTrueRulePacs004(Document, map);
		retVal = amendmentIndicatorFalseRulePacs004(Document, map);
		retVal = returnedInstructedAmountAndExchangeRate1RulePacs004(Document, map);
		retVal = returnedInstructedAmountAndExchangeRate2RulePacs004(Document, map);
		retVal = chargesInformationAndReturnedInstructedAmountRulePacs004(Document, map);
		/* retVal = groupReturnAndNumberOfTransactionsRulePacs004(Document, map);
		retVal = groupReturnAndReturnReasonRulePacs004(Document, map); */
	}

	return retVal;
}

