			prvsInstgAgt3NmPath = '/Document/PmtRtr/TxInf/RtrChain/PrvsInstgAgt3/FinInstnId/Nm';
			prvsInstgAgt3Nm = getValueFromPath(Document, prvsInstgAgt3NmPath);
