			prvsInstgAgt3CtryPath = '/Document/PmtRtr/TxInf/RtrChain/PrvsInstgAgt3/FinInstnId/PstlAdr/Ctry';
			prvsInstgAgt3Ctry = getValueFromPath(Document, prvsInstgAgt3CtryPath);
