/*
**
* This function checks the code which is passed as a parameter in the list of codes present in hazelcast map.
* @param {string} path - The path for that particular code in message.
* @param {string} ExternalCodeHzlCastMap - The hazeelcast map name.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {Number} return 0 for valid message otherwise returns 1 for invalid message.
*/
function checkExternalCodelist(path, ExternalCodeHzlCastMap, Document, map) {
	var hazelCastInstance;
	var code;
	var ExternalCodeMap;
	var mapValue;
	var retVal = '';

	code = getValueFromPath(Document, path);

	logger.info("checkExternalCodelist: External codelist = " + ExternalCodeHzlCastMap);
	logger.info("checkExternalCodelist: code in message = " + code);

	if(code) {
		code = code.trim();
		mapValue = memTblGetTableValue(map, ExternalCodeHzlCastMap, code);

		logger.info("checkExternalCodelist: mapValue for " + ExternalCodeHzlCastMap + " = " + mapValue);	

		if(!mapValue) {
			retVal = 1;
			return retVal;		
		}
	}
	
	return retVal;
}

