/**
* This function calls the validation function for particular fields
* @param {String} pacs09ValdFlag - Pacs09 valid mx flag value.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns violation raised for invalid message.
*/
function target2ValidationRulesPacs09(pacs09ValdFlag, exchange){
	var retVal;
	retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	if(pacs09ValdFlag == "ERROR"){

		retVal = target2NameAndPslAddrRulePacs009(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = target2TownNameAndCountryRulePacs009(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = target2StructuredVsUnstructuredRulePacs009(exchange);
		if(retVal !=0){
			return retVal;
		}
		
		retVal = mxPacs009GrpHdrClrSys(Document, map); 
		if(retVal != 0){
			return retVal;
		}

		retVal = mxVdPacs009Vr00340SttlmPrty(Document, map);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxVdPacs009Vr00371CdtrAcctIdOthrId(Document, map);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxVdPacs009Vr00380DbtrcdtrBicfi(Document, map);
		if(retVal =! 0){
			return retVal;
		}

		retVal = mxVdPacs009Vr00260LclinstrmCdBicfi(Document, map);
		if(retVal =! 0){
			return retVal;
		}

		retVal =  mxVdPacs009Vr00670LclInstrmCd(Document, map);
		if(retVal = 0){
			return retVal;
		}

		retVal = mxPacs009CdtTrfTxInffValidationPhob(Document, map);
		if(retVal != 0){
			return retVal;
		}

		/*retVal = mxPacs009Vr00260CdtTrfTxInfSttlmPrty(Document, map);
		if(retVal != 0){
			return retVal;
		}*/

		retVal = mxPacs009BicfiInstgAgt(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxPacs009BicfiInstdAgt(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxPacs009BicfiIntrmyAgt3(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxPacs009BicfiCdtr(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxVdPacs009OrgIdAnybic(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = mxPacs009Vr00370(Document, map);
		if(retVal != 0){
			return retVal;
		}
		retVal = mxVdPacs009Vr00660LclInstrmCdManp(Document, map);
		if(retVal != 0){
			return retVal;
		}
		retVal = crossElementComplexRulePacs009(pacs09ValdFlag,Document, map);
		if(retVal != 0) {
			return retVal;
		}
	}

	if(pacs09ValdFlag == "WARNING"){
		retVal = target2TownNameAndCountryRulePacs009(exchange);
		retVal = target2NameAndPslAddrRulePacs009(exchange);
		retVal = target2StructuredVsUnstructuredRulePacs009(exchange);
		retVal = mxPacs009GrpHdrClrSys(Document, map);
		retVal = mxVdPacs009Vr00340SttlmPrty(Document, map);
		retVal = mxVdPacs009Vr00371CdtrAcctIdOthrId(Document, map);
		retVal = mxVdPacs009Vr00380DbtrcdtrBicfi(Document, map);
		retVal = mxVdPacs009Vr00260LclinstrmCdBicfi(Document, map);
		retVal = mxVdPacs009Vr00670LclInstrmCd(Document, map);
		retVal = mxPacs009CdtTrfTxInffValidationPhob(Document, map);
		//retVal = mxPacs009Vr00260CdtTrfTxInfSttlmPrty(Document, map);
		retVal = mxPacs009BicfiInstgAgt(exchange);
		retVal = mxPacs009BicfiInstdAgt(exchange);
		retVal = mxPacs009BicfiIntrmyAgt3(exchange);
		retVal = mxPacs009BicfiCdtr(exchange);
		retVal = mxVdPacs009OrgIdAnybic(exchange);
		retVal = mxPacs009Vr00370(Document, map);
		retVal = mxVdPacs009Vr00660LclInstrmCdManp(Document, map);
		retVal = crossElementComplexRulePacs009(pacs09ValdFlag,Document, map);
	}
	return retVal;
}

function  crossElementComplexRulePacs009(pacs09ValdFlag, Document, map) {
	var retVal;

	logger.info("In crossElementComplexRulePacs009");

	retVal = 0;

	if(pacs09ValdFlag == "ERROR") {
		
		retVal = settlementMethodAgentRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}  
		retVal = settlementMethodCoverRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = settlementMethodCoverAgentRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		retVal = settlementMethodClearingRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = debtorAgentAccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = creditorAgentAccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = intermediaryAgent2RulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = intermediaryAgent3RulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = intermediaryAgent1AccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = intermediaryAgent2AccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = intermediaryAgent3AccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = previousInstructingAgent1AccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = previousInstructingAgent2AccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = previousInstructingAgent3AccountRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = previousInstructionAgent2RulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = previousInstructionAgent3RulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = intermediaryAgent1RulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}
	}

	if(pacs09ValdFlag == "WARNING") {

		retVal = settlementMethodAgentRulePacs009(Document, map);
		retVal = settlementMethodCoverRulePacs009(Document, map);
		retVal = settlementMethodCoverAgentRulePacs009(Document, map);
		retVal = settlementMethodClearingRulePacs009(Document, map);
		retVal = debtorAgentAccountRulePacs009(Document, map);
		retVal = creditorAgentAccountRulePacs009(Document, map);
		retVal = intermediaryAgent2RulePacs009(Document, map);
		retVal = intermediaryAgent3RulePacs009(Document, map);
		retVal = intermediaryAgent1AccountRulePacs009(Document, map);
		retVal = intermediaryAgent2AccountRulePacs009(Document, map);
		retVal = intermediaryAgent3AccountRulePacs009(Document, map);
		retVal = previousInstructingAgent1AccountRulePacs009(Document, map);
		retVal = previousInstructingAgent2AccountRulePacs009(Document, map);
		retVal = previousInstructingAgent3AccountRulePacs009(Document, map);
		retVal = previousInstructionAgent2RulePacs009(Document, map);
		retVal = previousInstructionAgent3RulePacs009(Document, map);
		retVal = intermediaryAgent1RulePacs009(Document, map);
	}

	return retVal;
}

/**
* This function checks if clrsys is not equal to "TGT" and returns appropriate violation.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function mxPacs009GrpHdrClrSys(Document, map){
	var clrsysPath;
	var clrsys;
	var retVal;

	retVal = 0;
	clrsysPath = "/Document/FICdtTrf/GrpHdr/SttlmInf/ClrSys/Cd";
	clrsys = getValueFromPath(Document, clrsysPath);

	if(clrsys != "TGT"){
		setHeader(map, "PLCN_validMessage", false);
		retVal = setCommentsForTransaction("133", "1560", map);//setViolationErrOrWar(clrsysPath, "10-1560", "10-1560", map);
		return retVal;
	}

	return 0;
}

/**
* This function checks if LocalInstrument Code and SettlementPriority is not equal to "SBTI" and "URGT" and returns appropriate values.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function mxVdPacs009Vr00340SttlmPrty(Document, map){
	var lclinstrmCdPath;
	var lclinstrmCd;
	var sttlmprtyPath;
	var Sttlmprty;
	var retVal;

	retVal = 0;

	lclinstrmCdPath = "/Document/FICdtTrf/CdtTrfTxInf/PmtTpInf/LclInstrm/Cd";
	lclinstrmCd = getValueFromPath(Document, lclinstrmCdPath);

	if(lclinstrmCd){

		if(lclinstrmCd != "SBTI"){
			return retVal;
		}else{
			sttlmprtyPath = "/Document/FICdtTrf/CdtTrfTxInf/SttlmPrty";
			sttlmprty = getValueFromPath(Document, sttlmprtyPath);

			if(sttlmprty){

				if(sttlmprty != "URGT"){
					memTblSetTableValue(map, "TransTable", "TransValErrorPath", sttlmprtyPath);
					setHeader(map, "PLCN_validMessage", false);
					retVal = setCommentsForTransaction("767", "E028", map);
					return retVal;
				}
			}
		}
	}
	return retVal;
}

/**
* This function validates CreditorAccountId code and returns appropriate violations.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} validates and returns appropriate value.
*/
function mxVdPacs009Vr00371CdtrAcctIdOthrId(Document, map){
	var lclinstrmCdPath;
	var lclinstrmCd;
	var cdtracctidOthridPath;
	var cdtracctidOthrid;
	var retVal;
	var ibanPath;
	var ibanVal;
	var tp;
	var tpVal;
	var ccy;
	var ccyVal;
	var nm;
	var nmVal;
	var prxy;
	var prxyVal;
	var cdtracctid;
	var cdtracctidVal;

	retVal = 0;
	lclinstrmCdPath = "/Document/FICdtTrf/CdtTrfTxInf/PmtTpInf/LclInstrm/Cd";
	lclinstrmCd = getValueFromPath(Document, lclinstrmCdPath);

	if(lclinstrmCd){

		if(lclinstrmCd != "SBTI"){
			return retVal;
		}else{
			var message = inMsg.getBody(java.lang.String.class);
			if(isPatternPresent(message, "</CdtrAcct>")){
				cdtracctidOthridPath = "/Document/FICdtTrf/CdtTrfTxInf/CdtrAcct/Id/Othr/Id";
				cdtracctidOthrid = getValueFromPath(Document, cdtracctidOthridPath);

				ibanPath = "/Document/FICdtTrf/CdtTrfTxInf/CdtrAcct/Id/Iban";
				ibanVal = getValueFromPath(Document, ibanPath);

				tp = "/Document/FICdtTrf/CdtTrfTxInf/CdtrAcct/Tp";
				tpVal = getValueFromPath(Document, tp);

				ccy = "/Document/FICdtTrf/CdtTrfTxInf/CdtrAcct/Ccy";
				ccyVal = getValueFromPath(Document, ccy);

				nm = "/Document/FICdtTrf/CdtTrfTxInf/CdtrAcct/Nm";
				nmVal = getValueFromPath(Document, nm);

				prxy = "/Document/FICdtTrf/CdtTrfTxInf/CdtrAcct/Prxy";
				prxyVal = getValueFromPath(Document, prxy);

				if(ibanVal || tpVal || ccyVal || nmVal || prxyVal){
					//memTblSetTableValue(map, "transTable", "transValErrorPath", cdtracctidOthridPath);
					retVal = setCommentsForTransaction("767", "1560", map);
					setHeader(map, "PLCN_validMessage", false);
					return retVal;
				}
			}else{
				return retVal;
			}
		}
	}
}

