/*
**
* This function validates BIC structure.
* @param {String} bic - The BIC.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function bicIdentifier(bic, Document, map){
	var len;
	var str;
	var i;
	var C;

	logger.info("In bicIdentifier");
	
	if(bic == ""){
		return 0;
	}
	
	len = bic.length;
	if(len < 8 || len > 11){
		logger.info('bicIdentifier: 5774 in bicIdentifier');
		return 5774;
	}
	str = bic.substr(0, 6);
	//logger.info("str = "+str);
	i = 0;
	
	while(i < 6){
		C = str.substr((i), 1);
		//logger.info('C = '+C);
		
		if(C == '1' || !(isAlpha(C))){
			logger.info('bicIdentifier: 5774 in bicIdentifier');
			return 5774;
		}
		
		i++;
	}
	
	C = "";
	C = bic.substr(6, 1);
	if(C == "1" || C == "0" || !isAlphaNumeric(C)){
		logger.info('bicIdentifier: 5774 in bicIdentifier');
		return 5774;
	}
	
	C = "";
	C = bic.substr(7, 1);
	if((C == 'O' || C == 'o') || !isAlphaNumeric(C)){
		logger.info('bicIdentifier: 5774 in bicIdentifier');
		return 5774;
	}
	
	str = "";
	str = bic.substr(8, 3);
	i = 0;
	
	if(str){
		while(i < 3){
			C = str.substr((i), 1);
			if(!isAlphaNumeric(C)){
				logger.info('bicIdentifier: 5774 in bicIdentifier');
				return 5774;
			}
			i ++;
		}
	}
	return 0;
}

/*
**
* This function validates BIC.
* @param {String} bic - The BIC.
* @returns {Boolean} return true for valid bic otherwise returns false.
*/
function isValidBic(bic, map) {
	var value;

	logger.info("In isValidBic");

	value = memTblGetTableValue(map, "VALID_BICS", bic);

	if(value == 'Y') {
		return true;
	}else {
		return false;
	}
}

