function instructionIdentificationRulePacs8(Document, map){ //DONE 28 //SWIFT VALIDATION FAIL
	logger.info("In instructionIdentificationRulePacs8");
	var instrIdPath;
	var instrId;
	var retVal = 0;

	instrIdPath = '/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/PmtId/InstrId';
	instrId = getValueFromPath(Document, instrIdPath);

	if(instrId) {
		logger.info("In instructionIdentificationRulePacs8 : instrId ");
		logger.info("instrId: " +instrId[0]);
		logger.info("instrId: " + instrId[instrId.length-1])

		if(instrId[0] == "/" || instrId[instrId.length-1] == "/" || isPatternPresent(instrId, "//")) {
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("299", "7952", map);
			logger.info("This field must not start or end with a slash '/' and must not contain two consecutive slashes '//'");
			return retVal;
		}
	}
	return retVal;
}

function cbprValidationRulesPacs008(pacs08ValdFlagMx, exchange){
	logger.info("cbprValidationRulesPacs008");
	var retVal;
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	retVal = 0;
	var MsgTypecheck;
	MsgTypecheck = getHeader(map, "PLCN_MsgType");
	logger.trace("cbprValidationRulesPacs008:MsgTypecheck = "+MsgTypecheck);
	retVal = 0;

	if(pacs08ValdFlagMx == "ERROR") {

		//retVal = shaAndSharRulePacs8(Document, map);
		//if(retVal != 0) {
		// return retVal;
		//}

		retVal = cbprAgentNamePstlAdrRulePacs8(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = structuredvsUnstructuredRulePacs8(exchange);;
		if(retVal != 0) {
			return retVal;
		}

		retVal = cbprNameAnyBicRulePacs8(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = cbprPartyNamePstlAdrRulePacs8(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = cbprCredRulePacs8(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		if(MsgTypecheck && MsgTypecheck !=="LynxPacs008")
		{
			retVal = interbankSettlementCurrRulePacs8(Document, map);
			if(retVal != 0) {
				return retVal;
			}
		}

		retVal = instructionIdentificationRulePacs8(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = townNameAndCountryRulePacs8(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		/*retVal =  instForCdtrAgentPresenceOfCode(exchange)
		if(retVal != 0){
			return retVal;
		}*/

		logger.info("before ChargesInformationOccurenceRulePacs008");
		retVal = ChargesInformationOccurenceRulePacs008(exchange);
		logger.info("after ChargesInformationOccurenceRulePacs008");
		if(retVal != 0) {
			return retVal;
		}

		retVal = crossElementComplexRulePacs008(pacs08ValdFlagMx,Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal = gracePeriodHybridFormalRulePacs8(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = gracePeriodUnstructuredFormalRulePacs8(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = structured_TwnNm_cntry_RulePacs8(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		
	}
	return retVal;
}

