/**
* This function calls all the external codelist functions
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function externalCodelistValidationCbprPacs008(Document, map) {
	var val;
	var retVal = 0;
	var MsgTypecheck;
	MsgTypecheck = getHeader(map, "PLCN_MsgType");
	logger.info("cbprValidationRulesPacs008:MsgTypecheck = "+MsgTypecheck);

	logger.info("In externalCodelistValidationCbprPacs008");

	val = externalAccountIdentification1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = val;
	}

	val = externalCashAccountType1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalCategoryPurpose1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalClearingSystemIdentification1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalDiscountAmountType1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalDocumentLineType1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalGarnishmentType1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	if(MsgTypecheck && MsgTypecheck !=="LynxPacs008")
	{
		val = externalLocalInstrument1CodeCbprPacs008(Document, map);
		if(val) {
			retVal = retVal + val;
		}
	}
	
	val = externalOrganisationIdentification1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalPersonIdentification1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalProxyAccountType1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalPurpose1CodeCbprPacs008(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	logger.info("before externalServiceLevel1CodeCbprPacs008");
	val = externalServiceLevel1CodeCbprPacs008(Document, map);
	logger.info("after externalServiceLevel1CodeCbprPacs008");
	if(val) {
		retVal = retVal + val;
	}
	logger.info("before externalTaxAmountType1CodeCbprPacs008");
	val = externalTaxAmountType1CodeCbprPacs008(Document, map);
	logger.info("after externalTaxAmountType1CodeCbprPacs008");
	if(val) {
		retVal = retVal + val;
	}
	
	return retVal;
}

