function cbprValidationRulesPacs009(pacs09ValdFlag, exchange){
	logger.info("cbprValidationRulesPacs009");
	var retVal;
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var MsgTypecheck;
	MsgTypecheck = getHeader(map, "PLCN_MsgType");
	logger.info("cbprValidationRulesPacs009:MsgTypecheck = "+MsgTypecheck);
	retVal = 0;

	if(pacs09ValdFlag == "ERROR") {

		retVal = instructionIdentificationRulePacs009(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		if(MsgTypecheck && MsgTypecheck !=="LynxPacs009")
		{
			retVal = interbankSettlementCurrencyRulePacs009(Document, map);
			if(retVal != 0) {
				return retVal;
			}
		}

		retVal = cbprAgentNamePstlAdrRulePacs009(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = townNameAndCountryRulePacs009(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = structuredvsUnstructuredRulePacs009(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = crossElementComplexRulePacs009(pacs09ValdFlag,Document, map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = gracePeriodHybridFormalRulePacs9(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = gracePeriodUnstructuredFormalRulePacs9(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = structured_TwnNm_cntry_RulePacs9(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
	}
	return retVal;
}

