function interbankSettlementCurrencyRulePacs009(Document, map){ //DONE 31 //SWIFT FAILURE
	logger.info("interbankSettlementCurrencyRulePacs009");
	var intrBkSttlmAmtPath;
	var intrBkSttlmAmt;
	var retVal=0;

	intrBkSttlmAmtPath = '/Document/FICdtTrf/CdtTrfTxInf/IntrBkSttlmAmt/@Ccy';
	intrBkSttlmAmt = getValueFromPath(Document, intrBkSttlmAmtPath);

	if(intrBkSttlmAmt == "XAU" || intrBkSttlmAmt == "XAG" || 
		intrBkSttlmAmt == "XPD" || intrBkSttlmAmt == "XPT") {
		logger.info("The codes XAU, XAG, XPD and XPT are not allowed, as these are codes are only used for commodities");
		setHeader(map, "PLCN_validMessage", false);
		retVal = setCommentsForTransaction("184", "7951", map);
	}
	return retVal;
}

/**
* This function calls all the external codelist functions
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid message otherwise returns 1.
*/
function externalCodelistValidationCbprPacs009(Document, map) {
	var val;
	var retVal = 0;

	logger.info("In externalCodelistValidation");

	val = externalAccountIdentification1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = val;
	}

	val = externalCashAccountType1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalCategoryPurpose1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalClearingSystemIdentification1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalLocalInstrument1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalProxyAccountType1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalPurpose1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	val = externalServiceLevel1CodeCbprPacs009(Document, map);
	if(val) {
		retVal = retVal + val;
	}
	
	return retVal;
}

