/**
* This function calls IBAN validation rules for particular fields.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid IBAN otherwise returns 1.
*/
function ibanValidationCbprPacs009(exchange) {
	var val;
	var retVal = 0;

	logger.info("In ibanValidationCbprPacs008");

	val = validatePrvsInstgAgt1AcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = val;
	}

	val = validatePrvsInstgAgt2AcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validatePrvsInstgAgt3AcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateIntrmyAgt1AcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateIntrmyAgt2AcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateIntrmyAgt3AcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateDbtrAcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateDbtrAgtAcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateCdtrAgtAcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	val = validateCdtrAcctIbanCbprPacs009(exchange);
	if(val) {
		retVal = retVal + val;
	}

	return retVal;
}

/**
* This function validates IBAN for Debtor Account.
* @param {DOMTree} Document - The message.
* @param {HashMap} map - The header values.
* @returns {String} return 0 for valid IBAN otherwise returns 1.
*/
function validateDbtrAcctIbanCbprPacs009(exchange) {
	var path;
	var value;
	var validFlag;
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	logger.info("In validateDbtrAcctIban");
	path = "/Document/FICdtTrf/CdtTrfTxInf/DbtrAcct/Id/IBAN";
	value = getValueFromPath(Document, path);
	logger.info("validateDbtrAcctIban: IBAN value = " + value);

	if(value) {
		validFlag = IBAN.isValid(value);
		logger.info("validateDbtrAcctIban: validFlag value = " + validFlag);

		if(validFlag == false) {
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("65", "5714", map);
			retVal = 1;
		}

		//ibanUpper(exchange, path, value);
	}
	return retVal;
}

