function validateCdtrAgtAcctIbanCbprPacs004(exchange) {
	var path;
	var value;
	var validFlag;
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	logger.info("In validateCdtrAgtAcctIbanCbprPacs004");
	path = "/Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAgtAcct/Id/IBAN";
	value = getValueFromPath(Document, path);
	logger.info("validateCdtrAgtAcctIbanCbprPacs004: IBAN value = " + value);

	if(value) {
		validFlag = IBAN.isValid(value);
		logger.info("validateCdtrAgtAcctIbanCbprPacs004: validFlag value = " + validFlag);

		if(validFlag == false) {
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("46", "5714", map);
			retVal = 1;
		}

		//ibanUpper(exchange, path, value);
	}

	return retVal;
}

function interbankSettlementCurrencyRulePacs004(Document, map){ 
	logger.info("interbankSettlementCurrencyRulePacs004");
	var rtrdintrBkSttlmAmtPath;
	var rtrdintrBkSttlmAmt;
	var orgnlIntrBkSttlmAmtPath;
	var orgnlIntrBkSttlmAmt;
	var orgnlTxRefIntrBkSttlmAmtPath;
	var orgnlTxRefIntrBkSttlmAmt;
	var retVal = 0;

	rtrdintrBkSttlmAmtPath = '/Document/PmtRtr/TxInf/RtrdIntrBkSttlmAmt/@Ccy';
	rtrdintrBkSttlmAmt = getValueFromPath(Document, rtrdintrBkSttlmAmtPath);

	if(rtrdintrBkSttlmAmt == "XAU" || rtrdintrBkSttlmAmt == "XAG" || 
		rtrdintrBkSttlmAmt == "XPD" || rtrdintrBkSttlmAmt == "XPT") {
		logger.info("The codes XAU, XAG, XPD and XPT are not allowed, as these are codes are only used for commodities");
		setHeader(map, "PLCN_validMessage", false);
		retVal = setCommentsForTransaction("179", "7951", map);
	}

	orgnlIntrBkSttlmAmtPath = '/Document/PmtRtr/TxInf/OrgnlIntrBkSttlmAmt/@Ccy';
	orgnlIntrBkSttlmAmt = getValueFromPath(Document, orgnlIntrBkSttlmAmtPath);

	if(orgnlIntrBkSttlmAmt == "XAU" || orgnlIntrBkSttlmAmt == "XAG" || 
		orgnlIntrBkSttlmAmt == "XPD" || orgnlIntrBkSttlmAmt == "XPT") {
		logger.info("The codes XAU, XAG, XPD and XPT are not allowed, as these are codes are only used for commodities");
		setHeader(map, "PLCN_validMessage", false);
		retVal = setCommentsForTransaction("176", "7951", map);
	}

	orgnlTxRefIntrBkSttlmAmtPath = '/Document/PmtRtr/TxInf/OrgnlTxRef/IntrBkSttlmAmt/@Ccy';
	orgnlTxRefIntrBkSttlmAmt = getValueFromPath(Document, orgnlTxRefIntrBkSttlmAmtPath);

	if(orgnlTxRefIntrBkSttlmAmt == "XAU" || orgnlTxRefIntrBkSttlmAmt == "XAG" || 
		orgnlTxRefIntrBkSttlmAmt == "XPD" || orgnlTxRefIntrBkSttlmAmt == "XPT") {
		logger.info("The codes XAU, XAG, XPD and XPT are not allowed, as these are codes are only used for commodities");
		setHeader(map, "PLCN_validMessage", false);
		retVal = setCommentsForTransaction("826", "7951", map);
	}

	return retVal;

}

