function cbprPartyNameOrAnybicRulePacs004(exchange){
	var cdtrAnyBIC;
	var cdtrNm;
	var dbtrAnyBic;
	var dbtrNm;
	var orgtrNm;
	var orgtrAnyBIC;
	var cdtrPty;
	var dbtrPty;
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var Document1 = inMsg.getBody(java.lang.String.class);

	cdtrPty = isXmlNodePresent(Document, "RtrChain", "Cdtr", "<Pty>");
	cdtrAnyBIC = isXmlNodePresent3(Document, "RtrChain", "Cdtr", "Pty", "<AnyBIC>");

	cdtrNm = isXmlNodePresent3(Document, "RtrChain", "Cdtr", "Pty", "<Nm>");
	logger.info("cdtrNm:" +cdtrNm);

	if(cdtrPty && !cdtrAnyBIC) {
		if(!cdtrNm){
			logger.info("cdtr- If AnyBIC is Absent Then Name is mandatory");
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("658", "7949", map);			
		}
	}

	dbtrPty = isXmlNodePresent(Document, "RtrChain", "Dbtr", "<Pty>");

	dbtrAnyBic = isXmlNodePresent3(Document, "RtrChain", "Dbtr", "Pty", "<AnyBIC>");

	dbtrNm = isXmlNodePresent3(Document, "RtrChain", "Dbtr", "Pty", "<Nm>");

	if(dbtrPty && !dbtrAnyBic) {
		if(!dbtrNm){
			logger.info("dbtr-If AnyBIC is Absent Then Name is mandatory");
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("304", "7949", map);			
		}

	}

	orgtrNm = isXmlNodePresent(Document, "RtrRsnInf", "Orgtr", "<Nm>");
	
	orgtrAnyBIC = isXmlNodePresent(Document, "RtrRsnInf", "Orgtr", "<AnyBIC>");

	if(isPatternPresent(Document1, "<Orgtr>")){
		if(!orgtrAnyBIC && !orgtrNm){
			logger.info("Orgtr - If AnyBIC is Absent Then Name is mandatory");
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("778", "7949", map);
		}
	}
	return retVal;
}

