	//Creditor
	var cdtrPty = isXmlNodePresent(Document, "RtrChain", "Cdtr", "<Pty>");
	cdtrPstlAdr3 = isXmlNodePresent(Document, "RtrChain", "Cdtr", "<PstlAdr>");

