function cbprValidationRulesCamt057(camt057ValdFlagMx, exchange){
	var retVal;
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	retVal = 0;

	logger.info("In cbprValidationRulesCamt057");

	logger.info("cbprValidationRulesCamt057: camt057ValdFlagMx = " + camt057ValdFlagMx);

	if(camt057ValdFlagMx == "ERROR") {
		retVal = totalAmountCurrencyRulecamt57(Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal =  amountCurrencyRulecamt57(Document, map);
		if(retVal != 0){
			return retVal;
		}

		retVal = cbprNameAnyBicRulecamt057(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = structuredvsUnstructuredRulecamt057(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = cbprAgentNmPstlAdrRuleCamt057(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = cbprPartyNmPstlAdrRuleCamt057(exchange);
		if(retVal != 0) {
			return retVal;
		}

		retVal = cbprExpectedValueDateRule(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal =  cbprDebtorBicPresenceRule(exchange);
		if(retVal != 0){
			return retVal;
		}
	
		retVal =  cbprTownNameAndCountryRuleCamt57(exchange);
		if(retVal != 0){
			return retVal;
		}

		retVal = crossElementComplexRuleCamt057(camt057ValdFlagMx, Document, map);
		if(retVal != 0) {
			return retVal;
		}

		retVal =  gracePeriodHybridFormalRuleCamt057(exchange);
		if(retVal != 0){
			return retVal;
		}
	
		retVal =  gracePeriodUnstructuredFormalRuleCamt057(exchange);
		if(retVal != 0){
			return retVal;
		}
	}
	
	return retVal;
}

