function totalAmountAndAmount1RuleCamt057(Document, map) {
	var retVal ;
	var i;
	var flag = 0;
	var ItmAmtList = [];
	var amt1;
	var res2;
	var TtlAmtCcy;
	var ttlamt1;
	
	logger.info("In totalAmountAndAmount1RuleCamt057");
	retVal = 0;
	
	var TtlAmt = isXmlNodePresent(Document, "NtfctnToRcv", "Ntfctn", "</TtlAmt>"); //isXmlNodePresent2(Document, "TtlAmt");
	logger.info("totalAmountAndAmount1RuleCamt057: TtlAmt = " + TtlAmt);
	
	if(TtlAmt == true) {
		var Amt = isXmlNodePresent(Document, "Ntfctn", "Itm", "</Amt>"); //isXmlNodePresent4(Document, "Itm", "Amt");
		logger.info("totalAmountAndAmount1RuleCamt057: Amt = " + Amt);

		if(Amt == true ) {
			var amtTag = Document.getElementsByTagName("Amt");
			logger.info("totalAmountAndAmount1RuleCamt057: amtTag length = " + amtTag.length);

			for(i = 0; i < amtTag.length; i++)
			{
				amt1 = amtTag.item(i);
				
				res2 = amt1.getAttribute("Ccy")
				ItmAmtList.push(res2);
			}

			logger.info("totalAmountAndAmount1RuleCamt057: ItmAmtList = " + ItmAmtList);

			var ttlamtTag = Document.getElementsByTagName("TtlAmt");
			ttlamt1 = ttlamtTag.item(0);
			logger.info("totalAmountAndAmount1RuleCamt057: ttlamt1 = " + ttlamt1);	
			TtlAmtCcy = ttlamt1.getAttribute("Ccy");
			logger.info("totalAmountAndAmount1RuleCamt057: TtlAmtCcy = " + TtlAmtCcy);

			for(i = 0; i < ItmAmtList.length; i++) {
				if(ItmAmtList[i] != TtlAmtCcy) {
					flag = 1;
				}
			}

			if (flag == 1) {   
				setHeader(map, "PLCN_validMessage", false);
				retVal = setCommentsForTransaction("333", "7943", map);
				return retVal;
			}		
		}
	}

	return retVal;
}

