function ibanUpper(exchange, path, value) {	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var messageBody = inMsg.getBody(java.lang.String.class);

	value = value.toUpperCase();
	setValueInPath(Document, path, value);
	inMsg.setBody(messageBody);
}

function ChargesInformationOccurenceRulePacs008(exchange) {
	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var chargeBearerPath;
	var chargeBearer;
	var retVal = 0;
	var msgString = inMsg.getBody(java.lang.String.class);
	logger.info("In ChargesInformationOccurenceRulePacs008");

	//var msgString = convertDocumentToString(Document);
	logger.trace("ChargesInformationOccurenceRulePacs008: msgString =  " + msgString);
	logger.trace("ChargesInformationOccurenceRulePacs008: typeof msgString =  " + typeof msgString);

	chargeBearerPath = "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/ChrgBr";
	chargeBearer = getValueFromPath(Document, chargeBearerPath);
	logger.info("ChargesInformationOccurenceRulePacs008:chargeBearer = "+chargeBearer);  

	if(chargeBearer == "DEBT") {
		var res = msgString.match(/<ChrgsInf>/g);
		logger.info("ChargesInformationOccurenceRulePacs008: res = " + res);
		logger.info("ChargesInformationOccurenceRulePacs008: typeof res =  " + typeof res);
		
		if(res) {
			res = res.length;
			logger.info("ChargesInformationOccurenceRulePacs008: res = " + res);
		}
		
		if(res > 1){
			setHeader(map, "PLCN_validMessage",false);
			retVal = setCommentsForTransaction("347", "7981", map);
		}
	}
	return retVal;
}

function cbprValidationRulesPain001(pain001ValdFlagMx, exchange){
	logger.info("cbprValidationRulesPain001");
	var retVal;
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	retVal = 0;

	if(pain001ValdFlagMx == "ERROR") {
		logger.info("inside if loop");

		retVal = structuredvsUnstructuredRulePain001(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = townNameAndCountryFormalRulePain001(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = townNameAndCountryTextualRulePain001(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = cbprPartyNameTextualRulePain001(Document,map);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = cbprInstructionforCreditorAgent1TextualRulePain001(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = cbprInstructionforCreditorAgent2TextualRulePain001(exchange);
		if(retVal != 0) {
			return retVal;
		}
		retVal = cbprremittanceMutuallyExclusiveFormalRulePain001(exchange);
		if(retVal != 0) {
			return retVal;
		}
		
		retVal = crossElementComplexRulePain001(pain001ValdFlagMx,exchange); 
		if(retVal != 0) {
			return retVal;
		}	
	}
	return retVal;
}

