function cbprPartyNameTextualRulePain001(Document,map) { 
	
	logger.info("cbprPartyNameTextualRulePain001");
	var retVal = 0;
	
	//Initiating Party
	var initgPtyPstlAddrPath = '/Document/CstmrCdtTrfInitn/GrpHdr/InitgPty/PstlAdr';
	var initgPtyPstlAddr = getValueFromPath(Document, initgPtyPstlAddrPath);
	
	if(initgPtyPstlAddr){
		var initgPtyPathNm = '/Document/CstmrCdtTrfInitn/GrpHdr/InitgPty/Nm';
		var initgPtyNm = getValueFromPath(Document, initgPtyPathNm);
	
		if(!initgPtyNm){
			logger.info("If Postal Address is provided, then Name is mandatory. Name without address is allowed.");
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("128", "7950",map);
			return retVal;
		}
	}
	
	//Debtor
	var dbtrPstlAddrPath = '/Document/CstmrCdtTrfInitn/PmtInf/Dbtr/PstlAdr';
	var dbtrPstlAddr = getValueFromPath(Document, dbtrPstlAddrPath);
	
	if(dbtrPstlAddr){
		var dbtrPathNm = '/Document/CstmrCdtTrfInitn/PmtInf/Dbtr/Nm';
		var dbtrNm = getValueFromPath(Document, dbtrPathNm);
	
		if(!dbtrNm){
			logger.info("If Postal Address is provided, then Name is mandatory. Name without address is allowed.");
			setHeader(map, "PLCN_validMessage", false);
			retVal = setCommentsForTransaction("235", "7950",map);
			return retVal;
		}
	}
	return retVal;
}

