function paymentTypeInformationRulePain001(exchange) 
{
	var retVal ;

	logger.info("In paymentTypeInformationRulePain001");
	retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var Document1 = inMsg.getBody(java.lang.String.class);

	var temp = strStr(Document1, "<CdtTrfTxInf");
	logger.info("paymentTypeInformationRulePain001: temp = " + temp);
	res1 = removePattern(Document1, temp);
	logger.info("paymentTypeInformationRulePain001: res1 = " + res1);

	var res1 = isPatternPresent(res1, "<PmtTpInf>");
	logger.info("paymentTypeInformationRulePain001: res1 = " + res1);

	if(res1)
	{
		var res2 = isXmlNodePresent(Document, "PmtInf", "CdtTrfTxInf", "PmtTpInf");
		logger.info("paymentTypeInformationRulePain001: res2 = " + res2);

		if(res2)
		{
			setHeader(map,"PLCN_validMessage",false);
			logger.info("If PaymentTypeInformation is present, then CreditTransferTransactionInformation/PaymentTypeInformation is not allowed.");
			retVal = setCommentsForTransaction("498","7111", map);
			return retVal;
		}
	}
	return retVal;
}

