function townNameAndCountryRulePain002(exchange) {
	var stsRsnInfPstlAdrPath;
	var stsRsnInfPstlAdr;
	var stsRsnInfAddrLinePath;
	var stsRsnInfAddrLine;
	var	stsRsnInfTwnNmPath;
	var stsRsnInfTwnNm;
	var stsRsnInfNmPath;
	var stsRsnInfNm;
	
	logger.info("In townNameAndCountryRulePain002");
	var retVal=0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var Document1 = inMsg.getBody(java.lang.String.class);

	//StatusReasonInformation
	//stsRsnInfPstlAdrPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/PstlAdr/AdrLine';
	stsRsnInfPstlAdr = isXmlNodePresent(Document, "StsRsnInf", "Orgtr", "<PstlAdr>");

	stsRsnInfAddrLinePath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/PstlAdr/AdrLine';
	stsRsnInfAddrLine = getValueFromPath(Document, stsRsnInfAddrLinePath);

	stsRsnInfTwnNmPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/PstlAdr/TwnNm';
	stsRsnInfTwnNm = getValueFromPath(Document, stsRsnInfTwnNmPath);

	stsRsnInfNmPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/PstlAdr/Nm';
	stsRsnInfNm = getValueFromPath(Document, stsRsnInfNmPath);

	stsRsnInfBicfiPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/Id/OrgId/AnyBIC';
	stsRsnInfBicfi = getValueFromPath(Document, stsRsnInfBicfiPath);

	if(isXmlNodePresent(Document, "TxInfAndSts", "StsRsnInf", "<Orgtr>")) {
			if(stsRsnInfPstlAdr){
				if(!stsRsnInfAddrLine && (!stsRsnInfTwnNm || !stsRsnInfNm)){
					setHeader(map, "PLCN_validMessage", false);
					logger.info("StsRsnInf-If PostalAddress is used & if AddressLine is absent then Country and Town name must be present");
					retVal = setCommentsForTransaction("177", "7926", map);
					return retVal;
				}
			}
		}
	return retVal;
}

function cbprOrgtrNamePstlAdrFormalRule2Pain002(exchange) {
	var stsRsnInfPstlAdrPath;
	var stsRsnInfPstlAdr;
	var stsRsnInfNmPath;
	var stsRsnInfNm;
	
	logger.info("In cbprOrgtrNamePstlAdrFormalRule2Pain002");
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var Document1 = inMsg.getBody(java.lang.String.class);

	//StatusReasonInformation
	//stsRsnInfPstlAdrPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/PstlAdr';
	stsRsnInfPstlAdr = isXmlNodePresent(Document, "StsRsnInf", "Orgtr", "<PstlAdr>");
	
	if(isPatternPresent(Document1, "<Orgtr>")) {
		if(stsRsnInfPstlAdr){
			stsRsnInfNmPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/Nm';
			stsRsnInfNm = getValueFromPath(Document, stsRsnInfNmPath);
			if(!stsRsnInfNm){
				logger.info("If Postal Address is present, then Name is mandatory.");
				retVal = setCommentsForTransaction("177","7927", map);
				setHeader(map, "PLCN_validMessage", false);
				return retVal;
			}
		}
	}
	return retVal;
}

function cbprOrgtrAnyBICFormalRule1Pain002(exchange) {
	var stsRsnInfAnyBicPath;
	var stsRsnInfAnyBic;
	var stsRsnInfNmPath;
	var stsRsnInfNm;
	
	logger.info("In cbprOrgtrAnyBICFormalRule1Pain002");
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var Document1 = inMsg.getBody(java.lang.String.class);

	stsRsnInfAnyBicPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/Id/OrgId/AnyBIC';
	stsRsnInfAnyBic =getValueFromPath(Document,stsRsnInfAnyBicPath);

	stsRsnInfNmPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/StsRsnInf/Orgtr/Nm';
	stsRsnInfNm = getValueFromPath(Document,stsRsnInfNmPath);

	if(isXmlNodePresent(Document, "TxInfAndSts", "StsRsnInf", "<Orgtr>")) {
		if(!stsRsnInfAnyBic) {
			if(!stsRsnInfNm) {
				setHeader(map, "PLCN_validMessage", false);
				logger.info("If any BIC is absent, then Name is mandatory.");
				retVal = setCommentsForTransaction("177", "7949", map);
				return retVal;			
			}
		}
	}
	return retVal;
}

function transactionStatusRejectReasonFormalRulePain002(exchange) {
	var txStsValPath;
	var txStsVal;
	var stsRsnInfRsnValPath;
	var stsRsnInfRsnVal;
	
	logger.info("In transactionStatusRejectReasonFormalRulePain002");
	var retVal = 0;

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var Document1 = inMsg.getBody(java.lang.String.class);

	txStsValPath = '/Document/CstmrPmtStsRpt/OrgnlPmtInfAndSts/TxInfAndSts/TxSts';
	txStsVal =getValueFromPath(Document,txStsValPath);

	stsRsnInfRsnVal = isXmlNodePresent(Document, "TxInfAndSts", "StsRsnInf", "<Rsn>");

	if(txStsVal == "RJCT") {
		if(stsRsnInfRsnVal != true) {
				setHeader(map, "PLCN_validMessage", false);
				logger.info("If TransactionStatus/Code equals RJCT, then “Status Reason Information/Reason” is mandatory.");
				retVal = setCommentsForTransaction("220", "7129", map);
				return retVal;			
		}
	}
	return retVal;
}

